options = {}
for sku, rule in data['skus'].items():
    options[sku] = [q for q in data['quotes'] if q['sku'] == sku and rule['demand'] <= q['units'] <= rule['demand'] + 2 and q['arrival'] <= rule['deadline'] and q['quality'] == 'approved']
vendors = {v['id']: v for v in data['vendors']}
best = None
for selection in itertools.product(*options.values()):
    selected = {q['sku']: q for q in selection}
    used = set(q['vendor'] for q in selection)
    if len(used) < 3 or sum(q['carbon'] for q in selection) > data['carbon_cap']:
        continue
    if any(q['needs_same_vendor_sku'] and selected[q['needs_same_vendor_sku']]['vendor'] != q['vendor'] for q in selection):
        continue
    total = 0
    valid = True
    for vendor in used:
        terms = vendors[vendor]
        lots = [q for q in selection if q['vendor'] == vendor]
        units = sum(q['units'] for q in lots)
        if units > terms['unit_cap']:
            valid = False
            break
        gross = sum(q['units'] * q['unit_cents'] for q in lots)
        bps = terms['tier_bps'] if units >= terms['tier_units'] else 0
        merchandise = (gross * (10000 - bps) + 5000) // 10000
        shipping = terms['shipping_cents'] if gross < terms['free_shipping_gross'] else 0
        rebate = terms['rebate_cents'] if len(set(q['sku'] for q in lots)) >= 2 and merchandise >= terms['rebate_merchandise_min'] else 0
        total += merchandise + shipping - rebate
    if valid and (best is None or total < best):
        best = total
print(FINAL(str(best)))
